SELECT COUNT(*)
FROM verification_codes
WHERE recipient_type = #{recipientType}
  AND recipient = #{recipient}
  AND created_at >= #{startTime}
  AND status IN ('PENDING', 'VERIFIED', 'EXPIRED')

SELECT COUNT(*)
FROM verification_codes
WHERE ip_address = #{ipAddress}
